public function resolveAggregate(?User $user): FinancialInsightsScopeDecision
{
    if (! $user || ! $user->canDo(self::BASE_PERMISSION)) {
        return FinancialInsightsScopeDecision::denied();
    }

    $isGlobal = $user->canDo(self::GLOBAL_PERMISSION);
    $siteIds = $this->siteAccess->accessibleSiteIds(
        $user,
        $isGlobal ? [self::GLOBAL_PERMISSION] : [],
    );

    $clientIds = $siteIds === []
        ? []
        : Client::query()
            ->whereIn('site_id', $siteIds)
            ->when(
                ! $isGlobal,
                fn (Builder $clients): Builder => $clients->whereHas(
                    'supportWorkers',
                    fn (Builder $workers): Builder => $workers->whereKey($user->id),
                ),
            )
            ->orderBy('id')
            ->pluck('id')
            ->map(fn ($clientId): int => (int) $clientId)
            ->all();

    if ($isGlobal) {
        return FinancialInsightsScopeDecision::global($siteIds, $clientIds);
    }

    return $siteIds === []
        ? FinancialInsightsScopeDecision::denied()
        : FinancialInsightsScopeDecision::accessibleSites($siteIds, $clientIds);
}

public function accessibleSiteIds(?User $user, array $bypassPermissions = []): array
{
    $cacheKey = implode('|', [
        $user ? (string) ($user->getKey() ?? 'unsaved') : 'guest',
        $user ? (string) spl_object_id($user) : 'guest',
        implode(',', $bypassPermissions),
    ]);
    if (array_key_exists($cacheKey, $this->accessibleSiteIdsCache)) {
        return $this->accessibleSiteIdsCache[$cacheKey];
    }

    if (! $user) {
        return $this->accessibleSiteIdsCache[$cacheKey] = [];
    }

    if ($this->canBypass($user, $bypassPermissions)) {
        return $this->accessibleSiteIdsCache[$cacheKey] = Site::query()
            ->active()
            ->notArchived()
            ->whereNull('archived_at')
            ->orderBy('id')
            ->pluck('id')
            ->map(fn ($siteId) => (int) $siteId)
            ->all();
    }

    $user->loadMissing('hrEmployeeProfile');

    $profile = $user->hrEmployeeProfile;
    if (! $profile || ! $this->isCurrentEmployeeProfile($profile)) {
        return $this->accessibleSiteIdsCache[$cacheKey] = [];
    }

    $secondarySiteIds = is_array($profile?->secondary_site_ids)
        ? $profile->secondary_site_ids
        : [];

    $assignedSiteIds = collect([
        $profile?->primary_site_id,
        ...$secondarySiteIds,
    ])
        ->filter(fn ($siteId) => filled($siteId))
        ->map(fn ($siteId) => (int) $siteId)
        ->filter(fn (int $siteId) => $siteId > 0)
        ->unique()
        ->values()
        ->all();

    if ($assignedSiteIds === []) {
        return $this->accessibleSiteIdsCache[$cacheKey] = [];
    }

    $currentSiteIds = Site::query()
        ->active()
        ->notArchived()
        ->whereNull('archived_at')
        ->whereIn('id', $assignedSiteIds)
        ->pluck('id')
        ->map(fn ($siteId) => (int) $siteId)
        ->all();

    return $this->accessibleSiteIdsCache[$cacheKey] = array_values(array_filter(
        $assignedSiteIds,
        fn (int $siteId) => in_array($siteId, $currentSiteIds, true),
    ));
}

/**
 * @param  array<int, string>  $bypassPermissions
 */

public function canBypass(?User $user, array $bypassPermissions = []): bool
{
    if (! $user) {
        return false;
    }

    foreach ($bypassPermissions as $permission) {
        if ($user->canDo($permission)) {
            return true;
        }
    }

    return false;
}

/** @return array<int, int> */

public function canDo(string $permissionKey): bool
{
    $permissionKeys = $this->permissionLookupKeys($permissionKey);

    if ($this->relationLoaded('permissionOverrides')
        && $this->relationLoaded('roles')
        && $this->roles->every(fn (Role $role) => $role->relationLoaded('permissions'))) {
        $overrides = $this->permissionOverrides
            ->filter(fn (Permission $permission) => in_array($permission->key, $permissionKeys, true));

        if ($overrides->contains(fn (Permission $permission) => ! (bool) $permission->pivot->allowed)) {
            return false;
        }

        if ($overrides->contains(fn (Permission $permission) => (bool) $permission->pivot->allowed)) {
            return true;
        }

        return $this->roles->contains(
            fn (Role $role) => $role->permissions->contains(
                fn (Permission $permission) => in_array($permission->key, $permissionKeys, true),
            ),
        );
    }

    // 1) explicit deny override wins
    $deny = $this->permissionOverrides()
        ->whereIn('permissions.key', $permissionKeys)
        ->wherePivot('allowed', false)
        ->exists();

    if ($deny) {
        return false;
    }

    // 2) explicit allow override
    $allow = $this->permissionOverrides()
        ->whereIn('permissions.key', $permissionKeys)
        ->wherePivot('allowed', true)
        ->exists();

    if ($allow) {
        return true;
    }

    // 3) role permissions
    return $this->roles()
        ->whereHas('permissions', fn ($q) => $q->whereIn('key', $permissionKeys))
        ->exists();
}

/**
 * Legacy permission keys kept as policy-layer synonyms while routes and
 * controllers use the canonical namespace.
 *
 * @return list<string>
 */

public static function denied(): self
{
    return new self(FinancialInsightsScope::Denied, [], []);
}

public static function global(
    array $siteIds,
    array $clientIds,
    ?int $siteId = null,
    ?int $clientId = null,
): self {
    return new self(FinancialInsightsScope::Global, $siteIds, $clientIds, $siteId, $clientId);
}

/**
 * @param  list<int>  $siteIds
 * @param  list<int>  $clientIds
 */

public static function accessibleSites(array $siteIds, array $clientIds, ?int $siteId = null): self
{
    return new self(FinancialInsightsScope::AccessibleSite, $siteIds, $clientIds, $siteId);
}

/**
 * @param  list<int>  $siteIds
 * @param  list<int>  $clientIds
 */

public function isDenied(): bool
{
    return $this->scope === FinancialInsightsScope::Denied;
}

public function getSiteSummaries(array $siteIds, ?Carbon $from = null, ?Carbon $to = null): array
{
    $to = $to ?? Carbon::now();
    $from = $from ?? $to->copy()->subMonths(1)->startOfMonth();

    $sites = Site::query()
        ->whereIn('id', $siteIds)
        ->active()
        ->notArchived()
        ->whereNull('archived_at')
        ->whereIn('type', ['house', 'facility'])
        ->get();
    $siteIds = $sites->pluck('id')->map(fn ($siteId): int => (int) $siteId)->all();

    // Batch staffing costs for all sites in one query
    $staffingBySite = $this->staffingCostService->perSiteComparison($siteIds, $from, $to);

    $summaries = [];

    foreach ($sites as $site) {
        $breakdown = $this->siteCostService->breakdown($site->id, $from, $to);
        $cpr = $this->costPerResidentService->calculate($site->id, $from, $to);
        $staffing = $staffingBySite[$site->id] ?? ['wages' => '0.00', 'employer_oncost' => '0.00', 'total' => '0.00', 'oncost_pct' => '0.0'];

        $summaries[] = [
            'site_id' => $site->id,
            'site_name' => $site->name,
            'site_type' => $site->type,
            'total_cost' => $breakdown['total'],
            'cost_per_resident' => $cpr['cost_per_resident'],
            'avg_residents' => $cpr['avg_residents'],
            'staffing' => [
                'wages' => $staffing['wages'],
                'employer_oncost' => $staffing['employer_oncost'],
                'total_staffing_cost' => $staffing['total'],
                'oncost_pct_of_wages' => $staffing['oncost_pct'],
            ],
        ];
    }

    usort($summaries, fn ($a, $b) => bccomp($b['total_cost'], $a['total_cost'], 2));

    return [
        'period' => ['from' => $from->toDateString(), 'to' => $to->toDateString()],
        'sites' => $summaries,
    ];
}

public function breakdown(int $siteId, Carbon $from, Carbon $to): array
{
    $rows = FinCostAllocation::forSite($siteId)
        ->forPeriod($from, $to)
        ->select('event_type', DB::raw('SUM(amount) as total_amount'), DB::raw('COUNT(*) as entry_count'))
        ->groupBy('event_type')
        ->orderByDesc('total_amount')
        ->get();

    $categories = [];
    $grandTotal = '0';

    foreach ($rows as $row) {
        $amount = number_format((float) $row->total_amount, 2, '.', '');
        $categories[$row->event_type] = [
            'amount' => $amount,
            'label' => $this->eventTypeLabel($row->event_type),
            'count' => (int) $row->entry_count,
        ];
        $grandTotal = bcadd($grandTotal, $amount, 2);
    }

    return [
        'categories' => $categories,
        'total' => $grandTotal,
        'site_id' => $siteId,
        'period_from' => $from->toDateString(),
        'period_to' => $to->toDateString(),
    ];
}

/**
 * Monthly cost trend for a site over a range of months.
 *
 * @return array<string, string>  month (Y-m) → total cost
 */

public function calculate(int $siteId, Carbon $from, Carbon $to): array
{
    $site = Site::findOrFail($siteId);
    $breakdown = $this->siteCostService->breakdown($siteId, $from, $to);
    $totalCost = $breakdown['total'];

    [$avgResidents, $method, $totalResidentDays, $periodDays] = $this->getAverageOccupancy($siteId, $from, $to);

    $costPerResident = bccomp($avgResidents, '0', 2) > 0
        ? bcdiv($totalCost, $avgResidents, 2)
        : $totalCost;

    return [
        'site_id' => $siteId,
        'site_name' => $site->name,
        'period_from' => $from->toDateString(),
        'period_to' => $to->toDateString(),
        'total_cost' => $totalCost,
        'avg_residents' => $avgResidents,
        'cost_per_resident' => $costPerResident,
        'breakdown' => $breakdown['categories'],
        'occupancy_method' => $method,
        'total_resident_days' => $totalResidentDays,
        'period_days' => $periodDays,
    ];
}

/**
 * Cost per resident across all active residential sites.
 *
 * @return array<int, array>
 */

public function perSiteComparison(array $siteIds, Carbon $from, Carbon $to): array
{
    $rows = FinCostAllocation::query()
        ->whereIn('site_id', $siteIds)
        ->forPeriod($from, $to)
        ->whereIn('event_type', ['payroll_cost', 'employer_oncost'])
        ->select('site_id', 'event_type', DB::raw('SUM(amount) as total'))
        ->groupBy('site_id', 'event_type')
        ->get();

    $bySite = [];
    foreach ($rows as $row) {
        $bySite[$row->site_id][$row->event_type] = (string) $row->total;
    }

    $results = [];
    foreach ($siteIds as $siteId) {
        $results[$siteId] = $this->buildBundle(collect($bySite[$siteId] ?? []));
    }

    return $results;
}

